using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis.CSharp;
using SqlSource.Diagnostics;
using SqlSource.Parsing.Tokens;
using SqlSource.Settings;

namespace SqlSource.Generation.Emitting;

/// <summary>
/// Writes the generated file of one type.
/// </summary>
internal static class TypeEmitter
{
    private const string Indent = "    ";

    // A query can be named like a member the type inherits: "GetType" hides object.GetType in the nested class, and
    // under SqlLocation.Direct a query can hide a member of a base class.  That is what was asked for, and the
    // compiler's request to add "new" (CS0108) is one that nobody can act on in generated code.  Neither is its
    // request to add "new" or "override" (CS0114) to a method that has the name and the parameters of an inherited
    // virtual method.
    private const string Header =
        "// <auto-generated/>\n"
        + "#nullable enable\n"
        + "#pragma warning disable CS0108, CS0114 // A query can have the name of an inherited member.\n"
        + "\n";

    /// <summary>
    /// Writes the file of <paramref name="input" />.
    /// </summary>
    /// <param name="input">The type and its parsed files.</param>
    /// <param name="property">What the project's properties say.</param>
    public static TypeOutput Emit(TypeQueries input, SettingsLevel property)
    {
        var type = input.Type.Type;
        if (input.Type.Diagnostics.Count > 0)
        {
            return new TypeOutput(input.HintName, null, input.Type.Diagnostics);
        }

        var diagnostics = ImmutableArray.CreateBuilder<DiagnosticInfo>();
        var members = SelectMembers(type, input.Files, input.FileSettings, diagnostics);
        return new TypeOutput(
            input.HintName,
            Write(type, members, property),
            new EquatableArray<DiagnosticInfo>(diagnostics.ToImmutable())
        );
    }

    /// <summary>
    /// Which of the type's files it can use.  A file contributes all of its queries or none: one that has a query
    /// with a name that cannot be used here (<c>SQLSRC008</c>, <c>SQLSRC009</c>) is left out, with a diagnostic for
    /// each such query when <paramref name="diagnostics" /> is given.
    /// </summary>
    /// <param name="type">The type.</param>
    /// <param name="files">The type's files, in member order.</param>
    /// <param name="diagnostics">Where the diagnostics go, or null when the caller does not report them.</param>
    /// <returns>One element for each of <paramref name="files" />: whether the type can use it.</returns>
    public static bool[] FindUsableFiles(
        TargetType type,
        EquatableArray<ParsedSqlFile> files,
        ImmutableArray<DiagnosticInfo>.Builder? diagnostics
    )
    {
        var containingTypeName = type.Placement == MemberPlacement.Nested ? type.NestedClass : type.Name;
        var usable = new bool[files.Count];
        var fileOfName = new Dictionary<string, string>(StringComparer.Ordinal);
        for (var index = 0; index < files.Count; index++)
        {
            var file = files[index];
            var isUsable = true;
            foreach (var query in file.Queries)
            {
                if (string.Equals(query.Name, containingTypeName, StringComparison.Ordinal))
                {
                    diagnostics?.Add(
                        DiagnosticInfo.Create(
                            SqlDiagnostics.QueryNamedLikeContainingType,
                            query.NameLocation,
                            type.Name,
                            query.Name
                        )
                    );
                    isUsable = false;
                }
                else if (fileOfName.TryGetValue(query.Name, out var firstFile))
                {
                    diagnostics?.Add(
                        DiagnosticInfo.Create(
                            SqlDiagnostics.DuplicateQueryName,
                            query.NameLocation,
                            query.Name,
                            firstFile,
                            type.Name
                        )
                    );
                    isUsable = false;
                }
            }

            if (!isUsable)
            {
                continue;
            }

            usable[index] = true;
            foreach (var query in file.Queries)
            {
                fileOfName.Add(query.Name, file.FileName);
            }
        }

        return usable;
    }

    // The queries of the files the type can use, each with what the metadata of its file's item says.
    private static List<(SqlQuery Query, string FileName, SettingsLevel Metadata)> SelectMembers(
        TargetType type,
        EquatableArray<ParsedSqlFile> files,
        EquatableArray<SettingsLevel> fileSettings,
        ImmutableArray<DiagnosticInfo>.Builder diagnostics
    )
    {
        var usable = FindUsableFiles(type, files, diagnostics);
        var members = new List<(SqlQuery Query, string FileName, SettingsLevel Metadata)>();
        for (var index = 0; index < files.Count; index++)
        {
            if (!usable[index])
            {
                continue;
            }

            var file = files[index];
            foreach (var query in file.Queries)
            {
                members.Add((query, file.FileName, fileSettings[index]));
            }
        }

        return members;
    }

    private static string Write(
        TargetType type,
        List<(SqlQuery Query, string FileName, SettingsLevel Metadata)> members,
        SettingsLevel property
    )
    {
        var builder = new StringBuilder(Header);
        var depth = 0;
        if (type.Namespace.Length > 0)
        {
            Open(builder, depth++, "namespace " + type.Namespace);
        }

        foreach (var declaration in type.Types)
        {
            Open(
                builder,
                depth++,
                "partial " + declaration.Keyword + " " + declaration.Name + declaration.TypeParameters
            );
        }

        if (type.Placement == MemberPlacement.Nested)
        {
            Open(builder, depth++, "private static class " + type.NestedClass);
        }

        var indent = GetIndent(depth);
        for (var index = 0; index < members.Count; index++)
        {
            if (index > 0)
            {
                _ = builder.Append('\n');
            }

            var (query, fileName, metadata) = members[index];
            var summaryXml = GetSummaryXml(query, fileName);
            var settings = QuerySettings.Resolve(query.Markers, type.Settings, metadata, property);

            // The member is built from the form that is emitted.  A form that was not built is the other one.
            var segments = settings.KeepComments ? query.KeptSegments ?? query.Segments : query.Segments;
            if (HasToken(segments))
            {
                MethodWriter.Append(builder, indent, summaryXml, query.Name, segments, settings.ValidateTokens);
                continue;
            }

            // Without a token the SQL is one literal segment.
            var sql = segments[0].Text;
            XmlDocWriter.AppendMember(builder, indent, summaryXml, sql);
            _ = builder
                .Append(indent)
                .Append("public const string ")
                .Append(query.Name)
                .Append(" = ")
                .Append(SymbolDisplay.FormatLiteral(sql, quote: true))
                .Append(";\n");
        }

        while (depth > 0)
        {
            _ = builder.Append(GetIndent(--depth)).Append("}\n");
        }

        return builder.ToString();
    }

    private static bool HasToken(EquatableArray<SqlSegment> segments)
    {
        foreach (var segment in segments)
        {
            if (segment.Kind == SqlSegmentKind.Token)
            {
                return true;
            }
        }

        return false;
    }

    private static string GetSummaryXml(SqlQuery query, string fileName) =>
        query.Summary is null
            ? "The <c>" + query.Name + "</c> query from <c>" + XmlDocWriter.Escape(fileName) + "</c>."
            : XmlDocWriter.Escape(query.Summary);

    private static void Open(StringBuilder builder, int depth, string header)
    {
        var indent = GetIndent(depth);
        _ = builder.Append(indent).Append(header).Append('\n').Append(indent).Append("{\n");
    }

    private static string GetIndent(int depth) => string.Concat(Enumerable.Repeat(Indent, depth));
}
